import{_ as s,o as t,c as a,a2 as l}from"./chunks/framework.C-si7TFR.js";const k=JSON.parse('{"title":"Shared and agent skills","description":"","frontmatter":{"title":"Shared and agent skills"},"headers":[],"relativePath":"guide/skills.md","filePath":"guide/skills.md"}'),n={name:"guide/skills.md"};function i(o,e,r,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="shared-and-agent-skills" tabindex="-1">Shared and agent skills <a class="header-anchor" href="#shared-and-agent-skills" aria-label="Permalink to &quot;Shared and agent skills&quot;">​</a></h1><p>Skills provide methods and conventions for a class of tasks. They are not MCP tools and do not replace model configuration.</p><h2 id="shared-skills" tabindex="-1">Shared skills <a class="header-anchor" href="#shared-skills" aria-label="Permalink to &quot;Shared skills&quot;">​</a></h2><p>A shared skill can be reused by multiple agents.</p><ol><li>From the workspace skill market or management entry, select <strong>New skill</strong>.</li><li>Enter its name and purpose, then upload a <code>SKILL.md</code> or add content through the current interface.</li><li>Select the shared skill in the agent&#39;s skills section.</li><li>Save the agent and verify with a task matching the skill&#39;s purpose.</li></ol><p>Changing a shared skill can affect multiple agents. Review its scope and never put project secrets, accounts or personal data in shared content.</p><h2 id="agent-specific-skills" tabindex="-1">Agent-specific skills <a class="header-anchor" href="#agent-specific-skills" aria-label="Permalink to &quot;Agent-specific skills&quot;">​</a></h2><p>Create and manage these in the target agent&#39;s <strong>Agent skills</strong> section. Each has a name, description, instructions, resources and tool bindings, including built-in and workflow tools.</p><ul><li><strong>Instructions</strong> describe the method this agent should follow.</li><li><strong>Resources</strong> provide supporting material; check size, content and sensitive data.</li><li><strong>Tool bindings</strong> define executable capabilities. Instructions alone do not grant permissions.</li></ul><p>An agent-specific version takes precedence over a same-named shared skill. Do not use same-name overrides to bypass review of shared content.</p><h2 id="skill-or-tool" tabindex="-1">Skill or tool? <a class="header-anchor" href="#skill-or-tool" aria-label="Permalink to &quot;Skill or tool?&quot;">​</a></h2><ul><li>To tell an agent <strong>how to work</strong>, use a skill.</li><li>To let an agent <strong>call an external system</strong>, use <a href="./mcp-tools.html">MCP tools</a>.</li><li>To enforce <strong>fixed steps</strong>, use <a href="./workflows.html">workflows</a>.</li><li>To <strong>retrieve internal documents</strong>, use <a href="./knowledge.html">knowledge</a>.</li></ul><p>Check references before deleting a skill. After changing one, test a clear success criterion instead of checking only that its name was saved.</p>',13)])])}const p=s(n,[["render",i]]);export{k as __pageData,p as default};
